<?php
require_once __DIR__ . '/../includes/auth.php'; require_login();
$user=current_user();$pdo=db();$userId=(int)($user['id']??0);$errors=[];
if($userId<=0){http_response_code(403);exit('Sesi pengguna tidak valid. Silakan login kembali.');}
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';
if($action==='add'){$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');$target=(float)($_POST['target_amount']??0);$current=(float)($_POST['current_amount']??0);$deadlineInput=trim($_POST['deadline']??'');$deadline=$deadlineInput!==''?$deadlineInput:null;
if($name==='')$errors[]='Nama target wajib diisi.';if($target<=0)$errors[]='Nominal target harus lebih dari 0.';if($current<0||$current>$target)$errors[]='Tabungan saat ini harus antara Rp 0 dan nominal target.';if($deadline!==null){$date=DateTime::createFromFormat('Y-m-d',$deadline);if(!$date||$date->format('Y-m-d')!==$deadline)$errors[]='Tanggal target tidak valid.';}
if(!$errors){$status=$current>=$target?'completed':'active';$stmt=$pdo->prepare('INSERT INTO financial_goals (user_id,name,description,target_amount,current_amount,deadline,status) VALUES (?,?,?,?,?,?,?)');$stmt->execute([$userId,$name,$description!==''?$description:null,$target,$current,$deadline,$status]);header('Location: index.php?success=1');exit;}}
elseif($action==='save'){$id=(int)($_POST['id']??0);$add=(float)($_POST['add_amount']??0);if($id>0&&$add>0){$stmt=$pdo->prepare("UPDATE financial_goals SET current_amount=LEAST(target_amount,current_amount+?),status=CASE WHEN current_amount+?>=target_amount THEN 'completed' ELSE 'active' END WHERE id=? AND user_id=? AND status<>'cancelled'");$stmt->execute([$add,$add,$id,$userId]);}header('Location: index.php');exit;}
elseif($action==='delete'){$stmt=$pdo->prepare('DELETE FROM financial_goals WHERE id=? AND user_id=?');$stmt->execute([(int)($_POST['id']??0),$userId]);header('Location: index.php');exit;}
elseif($action==='cancel'){$stmt=$pdo->prepare("UPDATE financial_goals SET status='cancelled' WHERE id=? AND user_id=?");$stmt->execute([(int)($_POST['id']??0),$userId]);header('Location: index.php');exit;}}
$stmt=$pdo->prepare('SELECT * FROM financial_goals WHERE user_id=? ORDER BY (deadline IS NULL),deadline ASC,id DESC');$stmt->execute([$userId]);$goals=$stmt->fetchAll(PDO::FETCH_ASSOC);$targetTotal=0;$savedTotal=0;$completedCount=0;foreach($goals as $g){$targetTotal+=(float)$g['target_amount'];$savedTotal+=(float)$g['current_amount'];if(($g['status']??'')==='completed')$completedCount++;}
$page_title='Target Keuangan';require_once __DIR__.'/../includes/header.php'; ?>
