<?php if(isset($_GET['success'])): ?><div class="alert-success">Target keuangan berhasil dibuat.</div><?php endif; ?><?php if($errors): ?><div class="alert-error"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif; ?>
<div class="summary-grid"><div class="summary-box"><span>Total target</span><strong>Rp <?=number_format($targetTotal,0,',','.')?></strong></div><div class="summary-box"><span>Total terkumpul</span><strong>Rp <?=number_format($savedTotal,0,',','.')?></strong></div><div class="summary-box"><span>Target tercapai</span><strong><?=$completedCount?> dari <?=count($goals)?></strong></div></div>
<section class="finance-card"><div class="card-head"><div><h2>Buat target baru</h2><p>Tentukan tujuan dan jumlah tabungan yang ingin dicapai.</p></div></div><div class="card-body"><form method="post"><input type="hidden" name="action" value="add"><div class="form-grid"><div class="form-group"><label for="goal-name">Nama target</label><input id="goal-name" name="name" maxlength="150" placeholder="Contoh: Beli laptop" required></div><div class="form-group"><label for="goal-description">Deskripsi <span class="muted" style="display:inline">(opsional)</span></label><input id="goal-description" name="description" placeholder="Ceritakan tujuan tabungan"></div><div class="form-group"><label for="goal-target">Nominal target (Rp)</label><input id="goal-target" type="number" name="target_amount" min="1" step="0.01" placeholder="Contoh: 8000000" required></div><div class="form-group"><label for="goal-current">Tabungan saat ini (Rp)</label><input id="goal-current" type="number" name="current_amount" min="0" step="0.01" value="0"></div><div class="form-group"><label for="goal-deadline">Tanggal target</label><input id="goal-deadline" type="date" name="deadline" min="<?=date('Y-m-d')?>"></div></div><div class="form-actions"><button class="btn primary" type="submit">＋ Simpan target</button></div></form></div></section>
<section class="finance-card"><div class="card-head"><div><h2>Target saya</h2><p>Pantau progres dan tambahkan tabungan kapan saja.</p></div></div><?php if(!$goals): ?><div class="empty">Belum ada target keuangan. Buat target pertama kamu di atas.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Target</th><th>Terkumpul</th><th>Nominal tujuan</th><th>Progres</th><th>Tambah tabungan</th><th>Status / aksi</th></tr></thead><tbody><?php foreach($goals as $goal):$target=(float)$goal['target_amount'];$current=(float)$goal['current_amount'];$percent=$target>0?min(100,($current/$target)*100):0;$status=$goal['status']??'active'; ?><tr><td><span class="primary-text"><?=htmlspecialchars($goal['name'],ENT_QUOTES,'UTF-8')?></span><span class="muted"><?=htmlspecialchars($goal['deadline']?:'Tanpa batas tanggal',ENT_QUOTES,'UTF-8')?><?php if(!empty($goal['description'])): ?><br><?=htmlspecialchars($goal['description'],ENT_QUOTES,'UTF-8')?><?php endif; ?></span></td><td><strong>Rp <?=number_format($current,0,',','.')?></strong></td><td>Rp <?=number_format($target,0,',','.')?></td><td><strong><?=number_format($percent,0,',','.')?>%</strong><div class="progress-track"><div class="progress-fill" style="width:<?=$percent?>%;background:<?=$status==='completed'?'#16a34a':'#3b82f6'?>"></div></div></td><td><?php if($status==='active'&&$percent<100): ?><form class="inline-form" method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)$goal['id']?>"><input type="number" name="add_amount" min="1" step="0.01" placeholder="Nominal Rp" required><button class="btn-small" type="submit">Tambah</button></form><?php else: ?><span class="muted">—</span><?php endif; ?></td><td><span class="badge <?=$status==='completed'?'success':($status==='cancelled'?'neutral':'warning')?>"><?=htmlspecialchars($status,ENT_QUOTES,'UTF-8')?></span><form method="post" onsubmit="return confirm('Hapus target ini?')" style="margin-top:8px"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$goal['id']?>"><button class="btn-small danger-btn" type="submit">Hapus</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
</div><?php require_once __DIR__.'/../includes/footer.php'; ?>